+		sample.err = fmt.Errorf("exit code %d: %s", rc, strings.TrimSpace(string(stderr)))
+	default:
+		sample.stats, sample.ifaces, sample.hasStates, sample.err = parseInterfaceSample(stdout)
+	}
+
+	return sample
+}
