+func drain(sink chan clablabruntime.Event) []clablabruntime.Event {
+	var events []clablabruntime.Event
+	for {
+		select {
+		case ev := <-sink:
+			events = append(events, ev)
+		default:
+			return events
+		}
+	}
+}
