+			_, err = r.kubeClient.CoreV1().Namespaces().
+				Get(context.Background(), "c9s-lab1", metav1.GetOptions{})
+			if tt.wantNamespace != (err == nil) {
+				t.Fatalf("namespace exists = %t (%v), want %t", err == nil, err, tt.wantNamespace)
